// Resolve instance_id com fallback seguro (aceita Webhook OU $input, e não quebra quando um node não executou)
const safeFirst = (nodeName) => {
  try {
    const arr = $items(nodeName);
    return arr?.[0]?.json ?? null;
  } catch (e) {
    return null;
  }
};

// 1) Fonte primária de entrada: $input (funciona vindo de IF/HTTP Request/etc)
const inputJson = $input.first()?.json ?? {};

// 2) Se existir o node "Resolve company_id1", usamos como complemento (fluxo do webhook)
const fromResolveCompany = safeFirst('Resolve company_id1') ?? {};

// 3) Body final: merge (input tem prioridade, mas mantém campos do resolveCompany se existirem)
const body = { ...fromResolveCompany, ...inputJson };

// Helpers para respostas de HTTP Request/Supabase REST (normalmente retornam ARRAY no .json)
const firstRow = (maybeArr) => (Array.isArray(maybeArr) ? (maybeArr[0] ?? null) : null);

// last conversation (HTTP Request que retorna array)
const lastConvArr = safeFirst('Lookup last conversation1');
const lastConvRow = firstRow(lastConvArr);

// phone/current/defaults (todos via HTTP Request REST, retornam array também)
const phoneRow   = firstRow(safeFirst('Lookup phone by last instance1'));
const currentRow = firstRow(safeFirst('Lookup current instance by phone1'));
const defRow     = firstRow(safeFirst('Lookup default instance1'));
const defAnyRow  = firstRow(safeFirst('Lookup default ANY1'));

// evolution state (node retorna objeto { instance: { state } } )
const evoState = safeFirst('Evolution check current1')?.instance?.state ?? null;

// company_id com fallback
const company_id =
  body.company_id ??
  lastConvRow?.company_id ??
  defRow?.company_id ??
  defAnyRow?.company_id ??
  null;

let resolved = null;
let strategy = null;

// 1) Se a instância atual está OPEN, mantém ela
if (currentRow?.instance_name && evoState === 'open') {
  resolved = currentRow.instance_name;
  strategy = 'current_instance(open)';
}
// 2) Se não está open, usa instância padrão (preferindo da empresa; fallback ANY)
else if (defRow?.instance_name) {
  resolved = defRow.instance_name;
  strategy = 'default_instance(company)';
}
else if (defAnyRow?.instance_name) {
  resolved = defAnyRow.instance_name;
  strategy = 'default_instance(any)';
}
// 3) Fallbacks (quando não tem default configurada)
else if (currentRow?.instance_name) {
  resolved = currentRow.instance_name;
  strategy = 'current_instance(any)';
}
else if (lastConvRow?.instance_id) {
  resolved = lastConvRow.instance_id;
  strategy = 'last_conversation(any)';
}
// 4) Fallback final: body.instance_id OU body.instance_name
else if (body.instance_id || body.instance_name) {
  resolved = body.instance_id ?? body.instance_name;
  strategy = 'fallback(body.instance_id|instance_name)';
}


// Binary: pega do Webhook se existir, senão do $input (caso venha de outro ramo/trigger)
let bin = null;
try {
  bin = $('Webhook').first()?.binary ?? null;
} catch (e) {
  bin = null;
}
if (!bin) {
  bin = $input.first()?.binary ?? null;
}

return [{
  json: {
    ...body,
    company_id,
    instance_id: resolved,
    resolved_strategy: strategy,
    resolved_phone_number: phoneRow?.phone_number ?? null,
    resolved_current_instance_name: currentRow?.instance_name ?? null,
    resolved_evolution_state: evoState,
  },
  binary: bin ?? undefined,
}];

const webhook = $('Webhook').first();
const body = webhook?.json?.body ?? webhook?.json ?? {};
const bin = webhook?.binary;

// --- TRATAMENTO DE TIPO E TEXTO ---
// Se o texto ou o tipo vier com a flag do CRM, ajustamos para o padrão do banco
if (body.text === "img" || body.type === "img") {
  body.type = "image";
  body.media_type = "image";
  body.text = "📷 Imagem enviada";
} else if (body.text === "audio" || body.type === "audio") {
  body.type = "audio";
  body.media_type = "audio";
  body.text = "🎵 Áudio enviado";
} else if (body.text === "doc" || body.text === "document" || body.type === "doc") {
  body.type = "document";
  body.media_type = "document";
  body.text = "📄 Documento enviado";
} else if (body.text === "video" || body.type === "video") {
  body.type = "video";
  body.media_type = "video";
  body.text = "🎥 Vídeo enviado";
}

// Se o type vier vazio ou não bater com nada acima, garantimos que seja text
if (!body.type) {
  body.type = "text";
}

return [{ 
  json: { 
    ...body, 
    company_id: body.company_id ?? null 
  }, 
  binary: bin 
}];

const identity = $('Resolve instance_id1').first().json;
const upload = $input.first().json;

const key =
  upload?.Key ||
  upload?.key ||
  upload?.path ||
  upload?.fullPath ||
  upload?.Name ||
  upload?.name ||
  null;

if (!key) {
  throw new Error('Upload não retornou uma chave de arquivo válida.');
}

const cleanKey = String(key).replace(/^\/+/, '');
const media_url = `${$env.SUPABASE_URL}/storage/v1/object/public/${encodeURI(cleanKey)}`;

return [{
  json: {
    ...identity,
    media_url
  }
}];

